#!/usr/bin/env sh
set -eu
umask 077

fail(){ printf '%s\n' "$1" >&2; exit 1; }
require(){ eval "value=\${$1-}"; [ -n "$value" ] || fail "missing $1"; }
require YUZHOU_SQLSERVER_ETL_LOGIN
require YUZHOU_SQLSERVER_ETL_PASSWORD
require YUZHOU_SQLSERVER_DATABASE
require YUZHOU_TRAINING_REWARD_EVENTS_RUN_ID
require YUZHOU_TRAINING_REWARD_EVENTS_OUTPUT_ROOT
require YUZHOU_BACKUP_SHA256
require YUZHOU_SOURCE_RESTORE_RECEIPT_PATH
require YUZHOU_MAPPING_CONTRACT_SHA256
printf %s "$YUZHOU_BACKUP_SHA256" | grep -Eq '^[0-9a-f]{64}$' || fail "invalid YUZHOU_BACKUP_SHA256"
printf %s "$YUZHOU_MAPPING_CONTRACT_SHA256" | grep -Eq '^[0-9a-f]{64}$' || fail "invalid YUZHOU_MAPPING_CONTRACT_SHA256"
source_binding="$(node --input-type=module - "$YUZHOU_SOURCE_RESTORE_RECEIPT_PATH" "$YUZHOU_BACKUP_SHA256" <<'NODE'
import {createHash} from "node:crypto";import {lstatSync,readFileSync,realpathSync,statSync} from "node:fs";import {isAbsolute,resolve} from "node:path";import {validateSourceRestoreReceipt} from "./scripts/hr-cutover/source-restore-receipt.mjs";
const [path,snapshot]=process.argv.slice(2);if(!isAbsolute(path)||resolve(path)!==path)throw Error("source restore receipt is required");const link=lstatSync(path),actual=realpathSync(path),info=statSync(actual);if(link.isSymbolicLink()||!info.isFile()||info.nlink!==1||(info.mode&0o777)!==0o600)throw Error("source restore receipt is unsafe");const bytes=readFileSync(actual),receipt=validateSourceRestoreReceipt(JSON.parse(bytes));if(receipt.sourceSnapshotSha256!==snapshot||receipt.productionImport!=="HOLD")throw Error("source restore receipt snapshot binding mismatch");process.stdout.write(JSON.stringify({sourceRestoreReceiptSha256:createHash("sha256").update(bytes).digest("hex"),sourceCatalogSha256:receipt.identities.catalogSha256}));
NODE
)" || fail "source restore receipt binding is invalid"

case "$YUZHOU_TRAINING_REWARD_EVENTS_RUN_ID" in *[!A-Za-z0-9._-]*|""|?|??|???|????) fail "invalid YUZHOU_TRAINING_REWARD_EVENTS_RUN_ID" ;; esac
container="${YUZHOU_SQLSERVER_CONTAINER:-jinhu_yuzhou_migration_lab-sqlserver-1}"
[ "$YUZHOU_SQLSERVER_ETL_LOGIN" != "sa" ] || fail "sa is forbidden for extraction"
[ "$(docker inspect --format '{{ index .Config.Labels "com.docker.compose.project" }}' "$container" 2>/dev/null || true)" = "jinhu_yuzhou_migration_lab" ] || fail "container is not the migration lab"
root="$YUZHOU_TRAINING_REWARD_EVENTS_OUTPUT_ROOT"; run_dir="$root/$YUZHOU_TRAINING_REWARD_EVENTS_RUN_ID"
[ ! -e "$run_dir" ] || fail "training reward receipt already exists"
mkdir -p "$root"; chmod 700 "$root"; mkdir "$run_dir"; chmod 700 "$run_dir"
raw="$run_dir/source-aggregate.json"; report="$run_dir/receipt.json"
query="SET NOCOUNT ON; SELECT CONVERT(int,is_read_only) sourceReadOnly, (SELECT COUNT_BIG(*) FROM dbo.course) courseRows, (SELECT COUNT_BIG(*) FROM dbo.train) trainRows, (SELECT COUNT_BIG(*) FROM dbo.train t JOIN dbo.person p ON p.person=t.person) trainLinkedPersonRows, (SELECT CONVERT(varchar(10),MIN(startdate),23) FROM dbo.train) trainFirstDate, (SELECT CONVERT(varchar(10),MAX(enddate),23) FROM dbo.train) trainLastDate, (SELECT COUNT_BIG(*) FROM dbo.trainhis) trainhisRows, (SELECT COUNT_BIG(*) FROM dbo.trainhis t JOIN dbo.person p ON p.person=t.person) trainhisLinkedPersonRows, (SELECT COUNT_BIG(*) FROM dbo.trainhis t JOIN dbo.person p ON p.person=t.person WHERE NULLIF(LTRIM(RTRIM(t.coursename)),'') IS NOT NULL AND LEN(t.coursename)<=160 AND t.startdate IS NOT NULL AND t.enddate IS NOT NULL AND t.enddate>=t.startdate AND t.hours BETWEEN 1 AND 999999) trainhisEligibleRows, (SELECT CONVERT(varchar(10),MIN(startdate),23) FROM dbo.trainhis) trainhisFirstDate, (SELECT CONVERT(varchar(10),MAX(enddate),23) FROM dbo.trainhis) trainhisLastDate, (SELECT COUNT_BIG(*) FROM dbo.jobtrain) jobtrainRows, (SELECT COUNT_BIG(*) FROM dbo.bonuscode) bonuscodeRows, (SELECT COUNT_BIG(*) FROM dbo.bonuscode b WHERE NULLIF(LTRIM(RTRIM(b.bonus)),'') IS NOT NULL AND LEN(b.bonus)<=64 AND NULLIF(LTRIM(RTRIM(b.bonusname)),'') IS NOT NULL AND LEN(b.bonusname)<=120 AND b.addsub>0) bonuscodePositiveEligibleRows, (SELECT COUNT_BIG(*) FROM dbo.bonuscode b WHERE NULLIF(LTRIM(RTRIM(b.bonus)),'') IS NOT NULL AND LEN(b.bonus)<=64 AND NULLIF(LTRIM(RTRIM(b.bonusname)),'') IS NOT NULL AND LEN(b.bonusname)<=120 AND b.addsub<0) bonuscodeNegativeEligibleRows, (SELECT COUNT_BIG(*) FROM dbo.bonuscode b WHERE b.addsub=0) bonuscodeZeroImpactRows, (SELECT COUNT_BIG(*) FROM dbo.bonuscode b WHERE b.addsub IS NULL) bonuscodeUnknownImpactRows, (SELECT COUNT_BIG(*) FROM dbo.bonusrecord) bonusrecordRows, (SELECT COUNT_BIG(*) FROM dbo.bonusrecord b JOIN dbo.person p ON p.person=b.person) bonusrecordLinkedPersonRows, (SELECT CONVERT(varchar(10),MIN(bonusdate),23) FROM dbo.bonusrecord) bonusrecordFirstDate, (SELECT CONVERT(varchar(10),MAX(bonusdate),23) FROM dbo.bonusrecord) bonusrecordLastDate FROM sys.databases WHERE name=DB_NAME() FOR JSON PATH, WITHOUT_ARRAY_WRAPPER;"
docker exec -e ETL_PASSWORD="$YUZHOU_SQLSERVER_ETL_PASSWORD" "$container" bash -lc '/opt/mssql-tools18/bin/sqlcmd -C -S localhost -U "$1" -P "$ETL_PASSWORD" -d "$2" -y 0 -w 65535 -Q "$3"' q "$YUZHOU_SQLSERVER_ETL_LOGIN" "$YUZHOU_SQLSERVER_DATABASE" "$query" >"$raw"
chmod 600 "$raw"
node -e 'const fs=require("fs"),crypto=require("crypto");const [rawPath,reportPath,runId,snapshot,binding,mapping]=process.argv.slice(1),raw=JSON.parse(fs.readFileSync(rawPath,"utf8")),source=JSON.parse(binding),sha=v=>crypto.createHash("sha256").update(v).digest("hex"),canonical=v=>Array.isArray(v)?`[${v.map(canonical).join(",")}]`:v&&typeof v==="object"?`{${Object.keys(v).sort().map(k=>`${JSON.stringify(k)}:${canonical(v[k])}`).join(",")}}`:JSON.stringify(v);const specs=[["dbo.course","course",false,false],["dbo.train","train",true,true],["dbo.trainhis","trainhis",true,true],["dbo.jobtrain","jobtrain",false,false],["dbo.bonuscode","bonuscode",false,false],["dbo.bonusrecord","bonusrecord",true,true]],rows=specs.map(([sourceTable,key,hasPerson,hasDates])=>({sourceTable,sourceRows:raw[`${key}Rows`],linkedPersonRows:hasPerson?raw[`${key}LinkedPersonRows`]:null,firstDate:hasDates?raw[`${key}FirstDate`]??null:null,lastDate:hasDates?raw[`${key}LastDate`]??null:null})),trainingHistory={sourceRows:raw.trainhisRows,linkedPersonRows:raw.trainhisLinkedPersonRows,eligibleRows:raw.trainhisEligibleRows,quarantinedRows:raw.trainhisRows-raw.trainhisEligibleRows},rewardCategories={sourceRows:raw.bonuscodeRows,rewardEligibleRows:raw.bonuscodePositiveEligibleRows,disciplineEligibleRows:raw.bonuscodeNegativeEligibleRows,zeroImpactRows:raw.bonuscodeZeroImpactRows,unknownImpactRows:raw.bonuscodeUnknownImpactRows,quarantinedRows:raw.bonuscodeRows-raw.bonuscodePositiveEligibleRows-raw.bonuscodeNegativeEligibleRows},validDate=v=>v===null||/^\d{4}-\d{2}-\d{2}$/.test(v),safeCount=v=>Number.isSafeInteger(v)&&v>=0;if(raw.sourceReadOnly!==1||rows.some(r=>!safeCount(r.sourceRows)||(r.linkedPersonRows!==null&&(!safeCount(r.linkedPersonRows)||r.linkedPersonRows>r.sourceRows))||!validDate(r.firstDate)||!validDate(r.lastDate))||!Object.values(trainingHistory).every(safeCount)||trainingHistory.linkedPersonRows>trainingHistory.sourceRows||trainingHistory.eligibleRows>trainingHistory.linkedPersonRows||trainingHistory.sourceRows!==trainingHistory.eligibleRows+trainingHistory.quarantinedRows||!Object.values(rewardCategories).every(safeCount)||rewardCategories.sourceRows!==rewardCategories.rewardEligibleRows+rewardCategories.disciplineEligibleRows+rewardCategories.quarantinedRows||rewardCategories.zeroImpactRows+rewardCategories.unknownImpactRows>rewardCategories.quarantinedRows)throw Error("invalid read-only training reward aggregate");const sourceAggregateSha256=sha(JSON.stringify(raw)),receipt={formatVersion:3,artifactKind:"yuzhou_training_reward_events_source_receipt",runId,operationMode:"read_only_aggregate",sourceReadOnly:true,sourceSnapshotSha256:snapshot,sourceRestoreReceiptSha256:source.sourceRestoreReceiptSha256,sourceCatalogSha256:source.sourceCatalogSha256,mappingContractSha256:mapping,sourceTables:rows,trainingHistory,rewardCategories,sourceAggregateSha256,sourceBusinessSha256:sha(canonical({sourceSnapshotSha256:snapshot,sourceRestoreReceiptSha256:source.sourceRestoreReceiptSha256,sourceCatalogSha256:source.sourceCatalogSha256,sourceTables:rows,trainingHistory,rewardCategories,sourceAggregateSha256})),productionImport:"HOLD"};fs.writeFileSync(reportPath,`${JSON.stringify(receipt,null,2)}\n`,{encoding:"utf8",mode:0o600,flag:"wx"});fs.chmodSync(reportPath,0o600);console.log(JSON.stringify({status:"PASS",runId,trainingHistory,rewardCategories,sourceBusinessSha256:receipt.sourceBusinessSha256,productionImport:"HOLD"}));' "$raw" "$report" "$YUZHOU_TRAINING_REWARD_EVENTS_RUN_ID" "$YUZHOU_BACKUP_SHA256" "$source_binding" "$YUZHOU_MAPPING_CONTRACT_SHA256"
